<section class="status-strip" aria-label="Customer overview"><div class="status-chip ok"><strong><?= count(array_filter($customers,fn($c)=>$c['status']==='active')) ?></strong><span>Active customers</span></div><div class="status-chip"><strong><?= count($customers) ?></strong><span>Total accounts</span></div><div class="status-chip"><strong><?= count(array_filter($customers,fn($c)=>!empty($c['last_login_at']))) ?></strong><span>Have signed in</span></div></section><section class="card"><div class="card-heading"><div><p class="section-kicker">Public accounts</p><h2>Customers</h2><p class="card-subtitle">These accounts exist only because the active industry module enables customer accounts.</p></div></div><?php if(!$customers): ?><div class="empty-state"><strong>No customer accounts</strong><span>Registered customers will appear here.</span></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Contact</th><th>Status</th><th>Created</th><th>Last sign-in</th><th></th></tr></thead><tbody><?php foreach($customers as $customer): ?><tr><td><strong><?= e($customer['name']) ?></strong><br><small>#<?= (int)$customer['id'] ?></small></td><td><a href="mailto:<?= e_attr($customer['email']) ?>"><?= e($customer['email']) ?></a><br><small><?= e($customer['phone']?:'No phone') ?></small></td><td><span class="badge <?= $customer['status']==='active'?'ok':'bad' ?>"><?= e(ucfirst($customer['status'])) ?></span></td><td><?= e($customer['created_at']) ?></td><td><?= e($customer['last_login_at']?:'Never') ?></td><td><form method="post"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)$customer['id'] ?>"><input type="hidden" name="status" value="<?= $customer['status']==='active'?'disabled':'active' ?>"><button class="btn small <?= $customer['status']==='active'?'danger':'secondary' ?>" <?= $customer['status']==='active'?'data-confirm="Disable this customer account? The customer will be signed out on their next request."':'' ?>><?= $customer['status']==='active'?'Disable':'Restore' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
